import { useEffect, useMemo, useRef, useState } from 'react';
import { Activity, AlertTriangle, Archive, ArrowDownToLine, ArrowRight, Bell, Box, Building2, Check, CheckCircle2, ChevronDown, ClipboardCheck, ClipboardList, Clock3, Download, FileBarChart, FileCheck2, FileText, Fingerprint, LayoutDashboard, LifeBuoy, ListChecks, LogOut, Menu, Package, PackageCheck, Plus, Search, Settings, ShieldCheck, Shirt, Truck, Users, X, RotateCcw, Eye, CircleCheck, CircleAlert, CircleDollarSign } from 'lucide-react';
import type { AppData, Role, Order, Employee, Product, OrderItem } from './types';
import { initialData } from './data/seed';

const roles:Role[]=['Administrador','Representante de sucursal','Gerente de ventas','Responsable de inventario','Supervisor / auditor'];
const navGroups=[
 {label:'GENERAL',items:[['Dashboard','dashboard',LayoutDashboard],['Actividad reciente','activity',Activity]]},
 {label:'OPERACIÓN COMERCIAL',items:[['Pedidos','orders',ClipboardList],['Catálogo y kits','catalog',Shirt],['Empleados','employees',Users],['Sucursales','branches',Building2],['Aprobaciones','approvals',ClipboardCheck]]},
 {label:'INVENTARIO Y LOGÍSTICA',items:[['Órdenes de inventario','inventory',Archive],['Preparación y paquetes','packages',Package],['Envíos y guías','shipments',Truck],['Recepción en sucursal','receiving',PackageCheck]]},
 {label:'ENTREGAS',items:[['Entregas individuales','deliveries',FileCheck2],['Incidencias','incidents',AlertTriangle],['Conformidades','conformities',Fingerprint]]},
 {label:'ADMINISTRACIÓN',items:[['Reportes','reports',FileBarChart],['Notificaciones','notifications',Bell],['Usuarios y permisos','users',ShieldCheck],['Configuración','settings',Settings]]}
] as const;
const statusClass=(s:string)=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll(' ','-');
const money=(n:number)=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n);
const now=()=>new Date().toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'});
const today=()=>new Date().toLocaleDateString('es-MX');
const id=(prefix:string)=>`${prefix}-${Date.now().toString().slice(-6)}`;

export default function App(){
 const [data,setData]=useState<AppData>(()=>{try{const saved=localStorage.getItem('control-pro-data');return saved?JSON.parse(saved):initialData}catch{return initialData}});
 const [page,setPage]=useState('dashboard'); const [role,setRole]=useState<Role>('Administrador'); const [search,setSearch]=useState(''); const [toast,setToast]=useState(''); const [modal,setModal]=useState(''); const [selected,setSelected]=useState(''); const [mobileNav,setMobileNav]=useState(false); const [filter,setFilter]=useState('Todos');
 useEffect(()=>{localStorage.setItem('control-pro-data',JSON.stringify(data))},[data]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(t)}},[toast]);
 const update=(fn:(d:AppData)=>AppData)=>setData(prev=>fn(structuredClone(prev)));
 const log=(action:string,detail:string)=>update(d=>{d.audit.unshift({id:id('AUD'),date:now(),user:role,action,detail});return d});
 const notify=(text:string)=>update(d=>{d.notifications.unshift({id:id('NOT'),text,read:false,date:today()});return d});
 const employees=data.employees.filter(e=>`${e.name} ${e.number} ${e.branch} ${e.job}`.toLowerCase().includes(search.toLowerCase()));
 const orders=data.orders.filter(o=>`${o.id} ${o.branch} ${o.status}`.toLowerCase().includes(search.toLowerCase()));
 const unread=data.notifications.filter(n=>!n.read).length;
 const can=(allowed:Role[])=>allowed.includes(role)||role==='Administrador';
 const open=(m:string,which='')=>{setModal(m);setSelected(which)};
 const go=(p:string)=>{setPage(p);setSearch('');setMobileNav(false);setFilter('Todos')};
 const reset=()=>{if(confirm('¿Restablecer toda la demostración? Se perderán los cambios locales.')){setData(structuredClone(initialData));setPage('dashboard');setModal('');setToast('Datos de demostración restaurados.')}};
 const approve=(order:Order)=>{if(order.status==='Aprobado'||order.inventoryId){setToast('Este pedido ya tiene una orden de inventario.');return}const inv=id('INV-2026');update(d=>{const o=d.orders.find(x=>x.id===order.id)!;o.status='Aprobado';o.reviewer=role;o.inventoryId=inv;d.inventory.unshift({id:inv,orderId:o.id,branch:o.branch,status:'Pendiente de revisión',created:today()});d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Pedido aprobado',detail:`${o.id} · orden ${inv} generada`});d.notifications.unshift({id:id('NOT'),text:`Pedido ${o.id} aprobado. Orden ${inv} generada.`,read:false,date:today()});return d});setModal('');setToast(`Pedido aprobado. Se generó ${inv}.`)};
 const submitOrder=(form:HTMLFormElement)=>{const fd=new FormData(form);const branch=String(fd.get('branch')||'Toluca');const employeeId=String(fd.get('employee')||'');const productId=String(fd.get('product')||'');const size=String(fd.get('size')||'M');const qty=Number(fd.get('qty')||1);const product=data.products.find(p=>p.id===productId);if(!employeeId||!product){setToast('Selecciona empleado y producto.');return}const employee=data.employees.find(e=>e.id===employeeId);if(!employee){setToast('Empleado no encontrado.');return}if(!product.jobs.includes(employee.job)&&!String(fd.get('exception')||'').trim()){setToast(`El producto no está autorizado para ${employee.job}. Solicita una excepción con justificación.`);return}const orderId=id('PED-2026');const item:OrderItem={employeeId,productId,size,qty,...(!product.jobs.includes(employee.job)?{exception:String(fd.get('exception'))}:{})};update(d=>{d.orders.unshift({id:orderId,branch,created:today(),status:'En revisión',items:[item],note:String(fd.get('note')||'')});d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Pedido enviado',detail:orderId});d.notifications.unshift({id:id('NOT'),text:`Nuevo pedido ${orderId} pendiente de aprobación.`,read:false,date:today()});return d});setModal('');setToast(`Pedido ${orderId} creado y enviado a revisión.`)};
 const addEmployee=(form:HTMLFormElement)=>{const f=new FormData(form);const e:Employee={id:id('EMP'),number:String(f.get('number')||''),name:String(f.get('name')||''),branch:String(f.get('branch')||'Toluca'),job:String(f.get('job')||'Administración'),active:true,joined:today()};if(!e.number||!e.name){setToast('Completa nombre y número de empleado.');return}if(data.employees.some(x=>x.number===e.number)){setToast('Ese número de empleado ya existe.');return}update(d=>{d.employees.push(e);d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Empleado creado',detail:e.name});return d});setModal('');setToast('Empleado agregado correctamente.')};
 const addProduct=(form:HTMLFormElement)=>{const f=new FormData(form);const p:Product={id:id('PR'),sku:String(f.get('sku')||''),name:String(f.get('name')||''),category:String(f.get('category')||'Prendas'),sizes:String(f.get('sizes')||'S,M,L,XL').split(',').map(s=>s.trim()).filter(Boolean),price:Number(f.get('price')||0),active:true,jobs:String(f.get('jobs')||'Administración').split(',').map(s=>s.trim()).filter(Boolean)};if(!p.sku||!p.name){setToast('Completa SKU y nombre del producto.');return}update(d=>{d.products.unshift(p);d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Producto creado',detail:p.name});return d});setModal('');setToast('Producto agregado al catálogo.')};
 const filteredOrders=orders.filter(o=>filter==='Todos'||o.status===filter);
 const allItems=(o:Order)=>o.items.reduce((n,i)=>n+i.qty,0);
 const totalCost=(o:Order)=>o.items.reduce((n,i)=>n+(data.products.find(p=>p.id===i.productId)?.price||0)*i.qty,0);
 const makePackage=(orderId:string)=>{const order=data.orders.find(o=>o.id===orderId);if(!order){setToast('Pedido no encontrado.');return}const people:string[]=[...new Set<string>(order.items.map(i=>i.employeeId))];update(d=>{const pid=id('PAQ-2026');d.packages.unshift({id:pid,orderId,employeeIds:people,status:'Preparado',tracking:['Paquete preparado · '+today()],received:false});const inv=d.inventory.find(i=>i.orderId===orderId);if(inv)inv.status='En preparación';const o=d.orders.find(x=>x.id===orderId);if(o)o.status='En preparación';d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Paquete preparado',detail:`${pid} · ${orderId}`});return d});setToast('Paquete creado y kits asignados.');};
 const registerGuide=(form:HTMLFormElement)=>{const f=new FormData(form);const pkg=data.packages.find(p=>p.id===String(f.get('package')));if(!pkg){setToast('Selecciona un paquete.');return}update(d=>{const p=d.packages.find(x=>x.id===pkg.id)!;p.carrier=String(f.get('carrier')||'Transportes Castores');p.guide=String(f.get('guide')||'');p.status='En tránsito';p.tracking.push(`Guía registrada · ${today()}`);d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Guía registrada',detail:`${p.id} · ${p.guide}`});d.notifications.unshift({id:id('NOT'),text:`Guía registrada para ${p.id}.`,read:false,date:today()});return d});setModal('');setToast('Guía registrada. El seguimiento es simulado.')};
 const simulateTracking=(pkgId:string)=>{const stages=['En tránsito','Llegada a centro de distribución','En reparto','Entregado por transportista'];update(d=>{const p=d.packages.find(x=>x.id===pkgId)!;const next=stages.find(s=>!p.tracking.some(t=>t.startsWith(s)));if(!next){setToast('El seguimiento ya llegó al último evento.');return d}p.tracking.push(`${next} · ${today()} (simulado)`);p.status=next==='Entregado por transportista'?'Entregado por transportista':next;if(next==='Entregado por transportista')d.notifications.unshift({id:id('NOT'),text:`El transportista reportó entregado ${p.id}. Falta confirmar recepción en sucursal.`,read:false,date:today()});d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Seguimiento actualizado',detail:`${p.id} · ${next}`});return d});setToast('Evento de seguimiento actualizado. La recepción sigue pendiente.')};
 const confirmReceive=(pkgId:string,difference='')=>{update(d=>{const p=d.packages.find(x=>x.id===pkgId)!;p.received=true;p.difference=difference;p.status=difference?'Recibido con diferencias':'Recibido en sucursal';if(difference)d.incidents.unshift({id:id('INC-2026'),orderId:p.orderId,packageId:p.id,type:difference,priority:'Media',status:'Abierta',description:`Diferencia detectada al recibir ${p.id}.`,created:today()});for(const emp of p.employeeIds){if(!d.deliveries.some(x=>x.packageId===p.id&&x.employeeId===emp))d.deliveries.push({id:id('ENT'),orderId:p.orderId,packageId:p.id,employeeId:emp,status:'Pendiente'});}d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Recepción confirmada',detail:`${p.id}${difference?' · '+difference:''}`});return d});setToast(difference?'Recepción registrada con incidencia.':'Recepción confirmada. Entregas individuales habilitadas.')};
 const changeIncident=(incidentId:string,status:string,resolution='')=>{update(d=>{const x=d.incidents.find(i=>i.id===incidentId)!;x.status=status;if(resolution)x.resolution=resolution;d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Incidencia actualizada',detail:`${x.id} · ${status}`});return d});setToast('Incidencia actualizada.')};
 const exportCsv=(rows:Record<string,unknown>[],name:string)=>{if(!rows.length){setToast('No hay datos para exportar.');return}const keys=Object.keys(rows[0]);const csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(r[k]??'').replaceAll('"','""')}"`).join(','))].join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href);setToast('Archivo CSV descargado.')};
 const kpis=[{label:'Pedidos activos',value:data.orders.filter(o=>!['Completado','Rechazado'].includes(o.status)).length,icon:ClipboardList,color:'blue'},{label:'Pendientes de aprobación',value:data.orders.filter(o=>['En revisión','Pendiente de aprobación'].includes(o.status)).length,icon:Clock3,color:'amber'},{label:'Paquetes en tránsito',value:data.packages.filter(p=>p.status==='En tránsito'||p.status==='En reparto').length,icon:Truck,color:'violet'},{label:'Incidencias abiertas',value:data.incidents.filter(i=>!['Resuelta','Cerrada'].includes(i.status)).length,icon:AlertTriangle,color:'red'}];
 return <div className="app-shell">
  <aside className={`sidebar ${mobileNav?'open':''}`}><div className="brand"><div className="brand-mark"><PackageCheck size={23}/></div><div><b>Control Pro</b><small>GESTIÓN INTEGRAL</small></div><button className="mobile-close" onClick={()=>setMobileNav(false)}><X size={18}/></button></div><div className="workspace"><span className="workspace-dot"/><div><b>Operación central</b><small>Entorno de demostración</small></div><ChevronDown size={15}/></div><nav>{navGroups.map(group=><div className="nav-group" key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(([label,key,Icon])=><button key={key} className={`nav-item ${page===key?'active':''}`} onClick={()=>go(key)}><Icon size={17}/><span>{label}</span>{key==='notifications'&&unread>0&&<em>{unread}</em>}</button>)}</div>)}</nav><div className="sidebar-bottom"><button className="demo-link" onClick={()=>go('demo')}><CircleCheck size={17}/><span><b>Modo demostración</b><small>Recorrer el proceso completo</small></span><ArrowRight size={15}/></button><div className="profile"><div className="avatar">{role.split(' ').map(s=>s[0]).slice(0,2).join('')}</div><div className="profile-text"><b>{role}</b><small>Usuario de prueba</small></div><button title="Restablecer demostración" onClick={reset}><RotateCcw size={16}/></button></div></div></aside>
  <main className="main-area"><header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav(true)}><Menu/></button><div className="crumb"><span>Control Pro</span><span className="slash">/</span><b>{pageTitle(page)}</b></div><div className="top-actions"><label className="searchbox"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar en este módulo…"/><kbd>⌘ K</kbd></label><button className="icon-button notification-button" onClick={()=>go('notifications')} title="Notificaciones"><Bell size={18}/>{unread>0&&<i/>}</button><div className="role-select"><span>Vista de</span><select value={role} onChange={e=>setRole(e.target.value as Role)} aria-label="Cambiar usuario de demostración">{roles.map(r=><option key={r}>{r}</option>)}</select></div></div></header>
  <div className="page-content"><div className="page-heading"><div><div className="eyebrow">PANEL DE CONTROL <span>•</span> {today()}</div><h1>{pageTitle(page)}</h1><p>{pageSubtitle(page)}</p></div><div className="heading-actions">{['orders','dashboard'].includes(page)&&<button className="btn primary" onClick={()=>open('new-order')}><Plus size={16}/> Nuevo pedido</button>}{page==='employees'&&<button className="btn primary" onClick={()=>open('new-employee')}><Plus size={16}/> Nuevo empleado</button>}{page==='catalog'&&<button className="btn primary" onClick={()=>open('new-product')}><Plus size={16}/> Nuevo producto</button>}{page==='shipments'&&<button className="btn primary" onClick={()=>open('new-guide')}><Plus size={16}/> Registrar guía</button>}</div></div>
  {page==='dashboard'&&<><div className="kpi-grid">{kpis.map(k=>{const Icon=k.icon;return <div className="kpi-card" key={k.label}><div className={`kpi-icon ${k.color}`}><Icon size={19}/></div><div className="kpi-label">{k.label}</div><div className="kpi-value">{k.value}</div><div className="kpi-foot"><span className="dot-green"/> Datos actualizados desde la operación</div></div>})}</div><div className="dashboard-grid"><section className="panel recent-panel"><div className="panel-header"><div><h2>Pedidos recientes</h2><p>Seguimiento de solicitudes por sucursal</p></div><button className="text-button" onClick={()=>go('orders')}>Ver todos <ArrowRight size={15}/></button></div><OrdersTable orders={orders.slice(0,5)} data={data} onOpen={o=>open('order-detail',o.id)} /></section><section className="panel"><div className="panel-header"><div><h2>Estado de operación</h2><p>Distribución actual de pedidos</p></div><Activity size={18} className="muted"/></div><div className="status-chart">{['En revisión','Aprobado','En preparación','En tránsito','Completado'].map((s,i)=>{const n=data.orders.filter(o=>o.status===s).length;const max=Math.max(1,...['En revisión','Aprobado','En preparación','En tránsito','Completado'].map(x=>data.orders.filter(o=>o.status===x).length));return <div className="bar-row" key={s}><div><span>{s}</span><b>{n}</b></div><div className="bar-track"><div className={`bar-fill b${i}`} style={{width:`${n/max*100}%`}}/></div></div>})}</div><div className="panel-divider"/><div className="mini-stat-row"><div><span className="mini-icon green"><CheckCircle2 size={16}/></span><span>Entregas completadas</span></div><b>{data.deliveries.filter(d=>d.status==='Entregado').length}</b></div><div className="mini-stat-row"><div><span className="mini-icon orange"><AlertTriangle size={16}/></span><span>Requieren atención</span></div><b>{data.incidents.filter(i=>!['Resuelta','Cerrada'].includes(i.status)).length}</b></div></section></div><div className="panel activity-panel"><div className="panel-header"><div><h2>Actividad reciente</h2><p>Últimos movimientos registrados en el sistema</p></div><button className="text-button" onClick={()=>go('activity')}>Ver historial <ArrowRight size={15}/></button></div><AuditList events={data.audit.slice(0,5)}/></div><div className="info-banner"><div className="info-icon"><ShieldCheck size={20}/></div><div><b>Entorno de demostración activo</b><p>Los cambios se guardan en este navegador. Las guías, firmas y eventos de transporte son simulados.</p></div><button className="text-button" onClick={()=>go('demo')}>Abrir recorrido <ArrowRight size={15}/></button></div></>}
  {page==='activity'&&<div className="panel"><div className="panel-header"><div><h2>Historial de actividad</h2><p>Registro cronológico de acciones del sistema</p></div><button className="btn secondary" onClick={()=>exportCsv(data.audit,'control-pro-auditoria.csv')}><Download size={15}/> Exportar CSV</button></div><AuditList events={data.audit.filter(a=>`${a.user} ${a.action} ${a.detail}`.toLowerCase().includes(search.toLowerCase()))}/></div>}
  {page==='orders'&&<div className="panel"><div className="toolbar"><div className="filter-pills">{['Todos','En revisión','Aprobado','En preparación','En tránsito','Completado','Rechazado'].map(s=><button key={s} className={filter===s?'selected':''} onClick={()=>setFilter(s)}>{s}</button>)}</div><button className="btn secondary" onClick={()=>exportCsv(filteredOrders.map(o=>({folio:o.id,fecha:o.created,sucursal:o.branch,empleados:new Set(o.items.map(i=>i.employeeId)).size,articulos:allItems(o),estado:o.status,total:totalCost(o)})),'control-pro-pedidos.csv')}><Download size={15}/> Exportar</button></div><OrdersTable orders={filteredOrders} data={data} onOpen={o=>open('order-detail',o.id)}/></div>}
  {page==='approvals'&&<div className="panel"><div className="panel-header"><div><h2>Bandeja de aprobación</h2><p>Revisa la solicitud antes de autorizar inventario.</p></div><span className="count-badge">{data.orders.filter(o=>o.status==='En revisión').length} pendientes</span></div><OrdersTable orders={data.orders.filter(o=>o.status==='En revisión').filter(o=>`${o.id} ${o.branch}`.toLowerCase().includes(search.toLowerCase()))} data={data} onOpen={o=>open('order-detail',o.id)} approval onApprove={approve} onReject={o=>open('reject-order',o.id)}/></div>}
  {page==='employees'&&<div className="panel"><div className="toolbar"><div className="filter-pills"><button className={filter==='Todos'?'selected':''} onClick={()=>setFilter('Todos')}>Todos</button><button className={filter==='Toluca'?'selected':''} onClick={()=>setFilter('Toluca')}>Toluca</button><button className={filter==='Querétaro'?'selected':''} onClick={()=>setFilter('Querétaro')}>Querétaro</button><button className={filter==='Puebla'?'selected':''} onClick={()=>setFilter('Puebla')}>Puebla</button></div><button className="btn secondary" onClick={()=>exportCsv(employees.map(e=>({numero:e.number,nombre:e.name,sucursal:e.branch,puesto:e.job,estado:e.active?'Activo':'Inactivo',alta:e.joined})),'control-pro-empleados.csv')}><Download size={15}/> Exportar CSV</button></div><table><thead><tr><th>EMPLEADO</th><th>NÚMERO</th><th>SUCURSAL</th><th>PUESTO</th><th>ESTADO</th><th>ALTA</th><th></th></tr></thead><tbody>{employees.filter(e=>filter==='Todos'||e.branch===filter).map(e=><tr key={e.id}><td><div className="person-cell"><div className="avatar small">{e.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><b>{e.name}</b><small>{e.id}</small></div></div></td><td>{e.number}</td><td>{e.branch}</td><td>{e.job}</td><td><Status value={e.active?'Activo':'Inactivo'}/></td><td>{e.joined}</td><td><button className="row-action" onClick={()=>open('employee-detail',e.id)}><Eye size={16}/></button></td></tr>)}</tbody></table><div className="table-footer">Mostrando {employees.filter(e=>filter==='Todos'||e.branch===filter).length} empleados <span>• Datos de demostración</span></div></div>}
  {page==='catalog'&&<div className="panel"><div className="toolbar"><div className="filter-pills">{['Todos','Batas','Prendas','Protección','Calzado','Accesorios'].map(s=><button className={filter===s?'selected':''} key={s} onClick={()=>setFilter(s)}>{s}</button>)}</div><button className="btn secondary" onClick={()=>exportCsv(data.products.map(p=>({sku:p.sku,producto:p.name,categoria:p.category,tallas:p.sizes.join('/'),precio:p.price,puestos:p.jobs.join('; '),estado:p.active?'Activo':'Inactivo'})),'control-pro-catalogo.csv')}><Download size={15}/> Exportar</button></div><div className="product-grid">{data.products.filter(p=>(filter==='Todos'||p.category===filter)&&`${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(search.toLowerCase())).map(p=><div className="product-card" key={p.id}><div className="product-visual"><Shirt size={30}/><span>{p.category}</span></div><div className="product-card-body"><div className="product-sku">{p.sku}</div><h3>{p.name}</h3><div className="product-price">{money(p.price)} <small>precio de referencia</small></div><div className="size-row">{p.sizes.slice(0,6).map(s=><span key={s}>{s}</span>)}</div><div className="job-tags">{p.jobs.slice(0,3).map(j=><span key={j}>{j}</span>)}</div><button className="btn secondary full" onClick={()=>open('product-detail',p.id)}>Ver producto <ArrowRight size={14}/></button></div></div>)}</div><div className="disclaimer">Los precios y reglas por puesto son datos ficticios de demostración; deben validarse con la empresa.</div></div>}
  {page==='branches'&&<div className="branch-grid">{['Toluca','Querétaro','Puebla'].map((b,i)=><div className="panel branch-card" key={b}><div className="branch-top"><div className="branch-icon"><Building2 size={21}/></div><Status value="Operativa"/></div><h2>Sucursal {b}</h2><p>{['Av. Independencia 120, Centro','Blvd. Bernardo Quintana 400','Av. Juárez 85, Centro'][i]}</p><div className="branch-metrics"><div><b>{data.employees.filter(e=>e.branch===b).length}</b><span>Empleados</span></div><div><b>{data.orders.filter(o=>o.branch===b&&!['Completado','Rechazado'].includes(o.status)).length}</b><span>Pedidos activos</span></div></div><button className="btn secondary full" onClick={()=>{setFilter(b);go('employees');setFilter(b)}}>Ver empleados <ArrowRight size={15}/></button></div>)}</div>}
  {page==='inventory'&&<div className="panel"><div className="panel-header"><div><h2>Órdenes de inventario</h2><p>Se generan al aprobar un pedido. No se duplican.</p></div><span className="count-badge">{data.inventory.length} órdenes</span></div><table><thead><tr><th>FOLIO</th><th>PEDIDO ORIGEN</th><th>SUCURSAL</th><th>FECHA</th><th>ARTÍCULOS</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>{data.inventory.filter(i=>`${i.id} ${i.orderId} ${i.branch} ${i.status}`.toLowerCase().includes(search.toLowerCase())).map(i=>{const o=data.orders.find(x=>x.id===i.orderId);return <tr key={i.id}><td><b>{i.id}</b></td><td>{i.orderId}</td><td>{i.branch}</td><td>{i.created}</td><td>{o?allItems(o):0}</td><td><Status value={i.status}/></td><td><button className="btn tiny secondary" onClick={()=>open('inventory-detail',i.id)}>Detalle</button>{i.status!=='Liberada para preparación'&&<button className="btn tiny primary" onClick={()=>{update(d=>{const inv=d.inventory.find(x=>x.id===i.id)!;inv.status='Liberada para preparación';d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Orden liberada',detail:i.id});return d});setToast('Orden liberada para preparación.')}}>Liberar</button>}</td></tr>})}</tbody></table>{data.inventory.length===0&&<Empty title="Sin órdenes de inventario" text="Aprueba un pedido para generar la primera orden."/>}</div>}
  {page==='packages'&&<div className="panel"><div className="panel-header"><div><h2>Preparación y paquetes</h2><p>Asigna los kits de una orden a paquetes de envío.</p></div><button className="btn primary" onClick={()=>open('new-package')}><Plus size={15}/> Crear paquete</button></div><table><thead><tr><th>PAQUETE</th><th>PEDIDO</th><th>EMPLEADOS / KITS</th><th>GUÍA</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>{data.packages.filter(p=>`${p.id} ${p.orderId} ${p.status} ${p.guide||''}`.toLowerCase().includes(search.toLowerCase())).map(p=><tr key={p.id}><td><b>{p.id}</b></td><td>{p.orderId}</td><td>{p.employeeIds.length}</td><td>{p.guide||'—'}</td><td><Status value={p.status}/></td><td><button className="btn tiny secondary" onClick={()=>open('package-detail',p.id)}>Ver contenido</button>{p.status==='Preparado'&&<button className="btn tiny primary" onClick={()=>open('new-guide',p.id)}>Registrar guía</button>}</td></tr>)}</tbody></table>{data.packages.length===0&&<Empty title="Aún no hay paquetes" text="Crea un paquete para una orden autorizada."/>}</div>}
  {page==='shipments'&&<div className="panel"><div className="panel-header"><div><h2>Envíos y guías</h2><p>Seguimiento de transporte con eventos simulados.</p></div><span className="demo-chip"><Activity size={14}/> Seguimiento simulado</span></div><table><thead><tr><th>PAQUETE</th><th>SUCURSAL</th><th>TRANSPORTISTA</th><th>GUÍA</th><th>ÚLTIMO EVENTO</th><th>ESTADO</th><th></th></tr></thead><tbody>{data.packages.filter(p=>p.guide&&`${p.id} ${p.guide} ${p.status}`.toLowerCase().includes(search.toLowerCase())).map(p=><tr key={p.id}><td><b>{p.id}</b><small className="cell-sub">{p.orderId}</small></td><td>{data.orders.find(o=>o.id===p.orderId)?.branch||'—'}</td><td>{p.carrier||'—'}</td><td>{p.guide}</td><td>{p.tracking[p.tracking.length-1]||'—'}</td><td><Status value={p.status}/></td><td><button className="btn tiny secondary" onClick={()=>open('tracking-detail',p.id)}>Seguimiento</button>{p.status!=='Entregado por transportista'&&<button className="btn tiny primary" onClick={()=>simulateTracking(p.id)}>Siguiente evento</button>}</td></tr>)}</tbody></table>{data.packages.every(p=>!p.guide)&&<Empty title="Sin guías registradas" text="Registra una guía para un paquete preparado."/>}</div>}
  {page==='receiving'&&<div className="panel"><div className="panel-header"><div><h2>Recepción en sucursal</h2><p>La entrega del transportista no confirma la recepción física.</p></div></div><table><thead><tr><th>PAQUETE</th><th>PEDIDO</th><th>SUCURSAL</th><th>KITS ESPERADOS</th><th>ESTADO DE RECEPCIÓN</th><th>ACCIÓN</th></tr></thead><tbody>{data.packages.filter(p=>`${p.id} ${p.orderId} ${p.status}`.toLowerCase().includes(search.toLowerCase())).map(p=><tr key={p.id}><td><b>{p.id}</b></td><td>{p.orderId}</td><td>{data.orders.find(o=>o.id===p.orderId)?.branch||'—'}</td><td>{p.employeeIds.length}</td><td><Status value={p.received?p.status:'Pendiente de recepción'}/></td><td>{!p.received?<button className="btn tiny primary" onClick={()=>open('receive-package',p.id)}>Verificar recepción</button>:<button className="btn tiny secondary" onClick={()=>open('package-detail',p.id)}>Ver detalle</button>}</td></tr>)}</tbody></table>{data.packages.length===0&&<Empty title="No hay paquetes por recibir" text="Los paquetes preparados aparecerán aquí."/>}</div>}
  {page==='deliveries'&&<div className="panel"><div className="panel-header"><div><h2>Entregas individuales</h2><p>Cada empleado requiere su propia confirmación de entrega.</p></div><span className="count-badge">{data.deliveries.filter(d=>d.status!=='Entregado').length} pendientes</span></div><table><thead><tr><th>EMPLEADO</th><th>PEDIDO</th><th>PAQUETE</th><th>ARTÍCULOS</th><th>ESTADO</th><th>CONFORMIDAD</th><th></th></tr></thead><tbody>{data.deliveries.filter(d=>{const e=data.employees.find(x=>x.id===d.employeeId);return `${e?.name} ${d.orderId} ${d.status}`.toLowerCase().includes(search.toLowerCase())}).map(d=>{const e=data.employees.find(x=>x.id===d.employeeId);const o=data.orders.find(x=>x.id===d.orderId);return <tr key={d.id}><td><div className="person-cell"><div className="avatar small">{e?.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><b>{e?.name||d.employeeId}</b><small>{e?.job}</small></div></div></td><td>{d.orderId}</td><td>{d.packageId}</td><td>{o?.items.filter(i=>i.employeeId===d.employeeId).length||0}</td><td><Status value={d.status}/></td><td>{d.signature?<span className="signed"><CheckCircle2 size={14}/> Firma registrada</span>:'—'}</td><td>{d.status!=='Entregado'&&<button className="btn tiny primary" onClick={()=>open('deliver',d.id)}>Entregar kit</button>}</td></tr>})}</tbody></table>{data.deliveries.length===0&&<Empty title="No hay entregas habilitadas" text="Confirma primero la recepción de un paquete."/>}</div>}
  {page==='conformities'&&<div className="panel"><div className="panel-header"><div><h2>Conformidades</h2><p>Registro de entregas, firmas y observaciones de recepción.</p></div><button className="btn secondary" onClick={()=>exportCsv(data.deliveries.map(d=>({entrega:d.id,empleado:data.employees.find(e=>e.id===d.employeeId)?.name,pedido:d.orderId,paquete:d.packageId,estado:d.status,fecha:d.signedAt||'',calificacion:d.rating||'',observaciones:d.note||''})),'control-pro-conformidades.csv')}><Download size={15}/> Exportar</button></div><table><thead><tr><th>EMPLEADO</th><th>PEDIDO</th><th>ESTADO</th><th>FECHA</th><th>VALORACIÓN</th><th>OBSERVACIONES</th></tr></thead><tbody>{data.deliveries.filter(d=>d.status==='Entregado').map(d=><tr key={d.id}><td>{data.employees.find(e=>e.id===d.employeeId)?.name}</td><td>{d.orderId}</td><td><Status value={d.status}/></td><td>{d.signedAt||'—'}</td><td>{d.rating?`${d.rating}/5`:'—'}</td><td>{d.note||'—'}</td></tr>)}</tbody></table>{data.deliveries.filter(d=>d.status==='Entregado').length===0&&<Empty title="Aún no hay conformidades" text="Las entregas firmadas aparecerán en este apartado."/>}</div>}
  {page==='incidents'&&<div className="panel"><div className="panel-header"><div><h2>Centro de incidencias</h2><p>Registra y da seguimiento a diferencias de artículos o paquetes.</p></div><button className="btn primary" onClick={()=>open('new-incident')}><Plus size={15}/> Nueva incidencia</button></div><table><thead><tr><th>FOLIO</th><th>TIPO</th><th>PEDIDO / EMPLEADO</th><th>PRIORIDAD</th><th>FECHA</th><th>ESTADO</th><th>ACCIÓN</th></tr></thead><tbody>{data.incidents.filter(i=>`${i.id} ${i.type} ${i.orderId} ${i.status}`.toLowerCase().includes(search.toLowerCase())).map(i=><tr key={i.id}><td><b>{i.id}</b></td><td>{i.type}<small className="cell-sub">{i.description}</small></td><td>{i.orderId}<small className="cell-sub">{data.employees.find(e=>e.id===i.employeeId)?.name||'Paquete'}</small></td><td><Status value={i.priority}/></td><td>{i.created}</td><td><Status value={i.status}/></td><td><button className="btn tiny secondary" onClick={()=>open('incident-detail',i.id)}>Gestionar</button></td></tr>)}</tbody></table>{data.incidents.length===0&&<Empty title="Sin incidencias" text="Cuando se detecte una diferencia, regístrala aquí."/>}</div>}
  {page==='reports'&&<Reports data={data} exportCsv={exportCsv}/>}
  {page==='notifications'&&<div className="panel"><div className="panel-header"><div><h2>Centro de notificaciones</h2><p>Alertas operativas de la demostración.</p></div><button className="btn secondary" onClick={()=>update(d=>{d.notifications.forEach(n=>n.read=true);return d})}>Marcar todas como leídas</button></div><div className="notification-list">{data.notifications.filter(n=>`${n.text} ${n.date}`.toLowerCase().includes(search.toLowerCase())).map(n=><div className={`notification-row ${n.read?'read':''}`} key={n.id}><div className="notification-icon"><Bell size={17}/></div><div className="notification-copy"><b>{n.text}</b><small>{n.date}</small></div>{!n.read&&<span className="unread-label">Nueva</span>}<button className="row-action" onClick={()=>update(d=>{const item=d.notifications.find(x=>x.id===n.id);if(item)item.read=true;return d})} title="Marcar como leída"><Check size={16}/></button></div>)}</div></div>}
  {page==='users'&&<div className="panel"><div className="panel-header"><div><h2>Usuarios y permisos de demostración</h2><p>Cambia el rol desde el selector superior para probar las vistas.</p></div><ShieldCheck size={22} className="muted"/></div><div className="role-cards">{roles.map((r,i)=><div className={`role-card ${r===role?'current':''}`} key={r}><div className="role-card-icon"><ShieldCheck size={19}/></div><b>{r}</b><p>{['Acceso completo a módulos y configuración.','Gestiona empleados, pedidos y recepción de su sucursal.','Revisa, aprueba, devuelve o rechaza pedidos.','Administra órdenes, preparación, paquetes y guías.','Consulta reportes, estados e historial de auditoría.'][i]}</p><button className={`btn ${r===role?'primary':'secondary'} full`} onClick={()=>setRole(r)}>{r===role?'Rol activo':'Cambiar a este rol'}</button></div>)}</div><div className="warning-note"><AlertTriangle size={17}/><p>La restricción visual por rol es solo demostrativa. En producción, los permisos deben validarse también en el backend y la API.</p></div></div>}
  {page==='settings'&&<div className="settings-grid"><div className="panel"><div className="panel-header"><div><h2>Reglas por puesto</h2><p>Productos autorizados para la solicitud normal.</p></div></div>{['Enfermería','Administración','Mantenimiento','Seguridad','Intendencia','Almacén'].map(job=><div className="rule-row" key={job}><div><b>{job}</b><small>{data.products.filter(p=>p.jobs.includes(job)).map(p=>p.name).join(', ')||'Sin productos asignados'}</small></div><span className="rule-count">{data.products.filter(p=>p.jobs.includes(job)).length} productos</span></div>)}<div className="disclaimer">Para editar las reglas globales, modifica los puestos autorizados de cada producto en el catálogo.</div></div><div className="panel"><div className="panel-header"><div><h2>Datos de demostración</h2><p>Preferencias y mantenimiento local.</p></div><Settings size={19} className="muted"/></div><div className="setting-action"><div><b>Restablecer los datos</b><p>Elimina los cambios de este navegador y recupera los datos de ejemplo.</p></div><button className="btn danger" onClick={reset}><RotateCcw size={15}/> Restablecer</button></div><div className="setting-action"><div><b>Exportar auditoría</b><p>Descarga el historial de acciones registrado en esta sesión.</p></div><button className="btn secondary" onClick={()=>exportCsv(data.audit.map(a=>({...a})),'control-pro-auditoria.csv')}><Download size={15}/> Exportar CSV</button></div><div className="setting-action"><div><b>Almacenamiento</b><p>Los cambios se guardan localmente mediante localStorage.</p></div><span className="demo-chip">Local</span></div></div></div>}
  {page==='demo'&&<DemoPage data={data} go={go} onReset={reset}/>}
  </div><footer className="footer"><span>© 2026 Control Pro</span><span><span className="footer-dot"/> Prototipo funcional · Datos simulados</span><span>Versión 1.0.0</span></footer></main>
  {modal&&<Modal title={modalTitle(modal,selected,data)} onClose={()=>setModal('')}><ModalContent modal={modal} selected={selected} data={data} role={role} onClose={()=>setModal('')} onToast={setToast} onUpdate={update} onApprove={approve} onSubmitOrder={submitOrder} onAddEmployee={addEmployee} onAddProduct={addProduct} onRegisterGuide={registerGuide} onConfirmReceive={confirmReceive} onIncidentChange={changeIncident} onOpen={open} onLog={log} /></Modal>}
  {toast&&<div className="toast"><CheckCircle2 size={18}/><span>{toast}</span><button onClick={()=>setToast('')}><X size={15}/></button></div>}
 </div>
}

function pageTitle(p:string){return ({dashboard:'Dashboard',activity:'Actividad reciente',orders:'Pedidos',catalog:'Catálogo y kits',employees:'Empleados',branches:'Sucursales',approvals:'Aprobaciones',inventory:'Órdenes de inventario',packages:'Preparación y paquetes',shipments:'Envíos y guías',receiving:'Recepción en sucursal',deliveries:'Entregas individuales',incidents:'Incidencias',conformities:'Conformidades',reports:'Reportes',notifications:'Notificaciones',users:'Usuarios y permisos',settings:'Configuración',demo:'Modo demostración'} as Record<string,string>)[p]||'Control Pro'}
function pageSubtitle(p:string){return ({dashboard:'Vista general de pedidos, inventario y entregas.',activity:'Consulta quién hizo qué y cuándo dentro de la operación.',orders:'Administra solicitudes consolidadas por sucursal y empleado.',catalog:'Productos, tallas, precios de referencia y elegibilidad por puesto.',employees:'Directorio centralizado de empleados y sus sucursales.',branches:'Consulta el estado operativo de cada ubicación.',approvals:'Revisa las solicitudes antes de autorizar la preparación.',inventory:'Órdenes generadas a partir de pedidos aprobados.',packages:'Agrupa kits por empleado y prepara los paquetes para envío.',shipments:'Guías y cronología de transporte. No hay conexión real con paqueterías.',receiving:'Verifica físicamente los paquetes recibidos en cada sucursal.',deliveries:'Entrega cada kit a su destinatario y registra conformidad individual.',incidents:'Documenta faltantes, daños, tallas incorrectas y resolución.',conformities:'Consulta evidencia de las entregas individuales finalizadas.',reports:'Indicadores operativos y exportaciones de datos.',notifications:'Avisos generados por los eventos de la operación.',users:'Perfiles de demostración y alcance visual de permisos.',settings:'Reglas configurables y herramientas del prototipo.',demo:'Recorre las etapas clave sin saltarte aprobaciones ni confirmaciones.'} as Record<string,string>)[p]||''}
function Status({value}:{value:string}){return <span className={`status status-${statusClass(value)}`}><i/>{value}</span>}
function OrdersTable({orders,data,onOpen,approval=false,onApprove,onReject}:{orders:Order[];data:AppData;onOpen:(o:Order)=>void;approval?:boolean;onApprove?:(o:Order)=>void;onReject?:(o:Order)=>void}){return <table><thead><tr><th>FOLIO</th><th>FECHA</th><th>SUCURSAL</th><th>EMPLEADOS</th><th>ARTÍCULOS</th><th>IMPORTE REF.</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>{orders.map(o=>{const count=new Set(o.items.map(i=>i.employeeId)).size;const total=o.items.reduce((n,i)=>n+(data.products.find(p=>p.id===i.productId)?.price||0)*i.qty,0);return <tr key={o.id}><td><b>{o.id}</b></td><td>{o.created}</td><td>{o.branch}</td><td>{count}</td><td>{o.items.reduce((n,i)=>n+i.qty,0)}</td><td>{money(total)}</td><td><Status value={o.status}/></td><td><div className="row-actions"><button className="row-action" title="Ver detalle" onClick={()=>onOpen(o)}><Eye size={16}/></button>{approval&&<><button className="row-action good" title="Aprobar" onClick={()=>onApprove?.(o)}><Check size={16}/></button><button className="row-action bad" title="Rechazar" onClick={()=>onReject?.(o)}><X size={16}/></button></>}</div></td></tr>})}</tbody></table>}
function AuditList({events}:{events:AppData['audit']}){return <div className="audit-list">{events.map(e=><div className="audit-row" key={e.id}><div className="audit-symbol"><Activity size={15}/></div><div className="audit-copy"><b>{e.action}</b><p>{e.detail}</p><small>{e.user} · {e.date}</small></div></div>)}{events.length===0&&<Empty title="Sin actividad" text="Los eventos aparecerán aquí conforme uses el sistema."/>}</div>}
function Empty({title,text}:{title:string;text:string}){return <div className="empty-state"><div><ClipboardList size={24}/></div><b>{title}</b><p>{text}</p></div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal"><div className="modal-header"><div><h2>{title}</h2><p>Control Pro · Entorno de demostración</p></div><button className="icon-button" onClick={onClose}><X size={18}/></button></div><div className="modal-content">{children}</div></div></div>}
function modalTitle(m:string,selected:string,data:AppData){if(m==='order-detail')return `Detalle del pedido ${selected}`;if(m==='employee-detail')return data.employees.find(e=>e.id===selected)?.name||'Detalle de empleado';if(m==='product-detail')return data.products.find(p=>p.id===selected)?.name||'Detalle de producto';if(m==='inventory-detail')return `Orden ${selected}`;if(m==='package-detail'||m==='tracking-detail'||m==='receive-package')return `${m==='receive-package'?'Recepción de ':m==='tracking-detail'?'Seguimiento de ':'Detalle de '}${selected}`;if(m==='deliver')return 'Registrar entrega individual';if(m==='incident-detail')return `Gestionar incidencia ${selected}`;return ({'new-order':'Crear pedido','new-employee':'Nuevo empleado','new-product':'Nuevo producto','new-guide':'Registrar guía de envío','new-package':'Crear paquete','new-incident':'Registrar incidencia','reject-order':'Devolver / rechazar pedido'} as Record<string,string>)[m]||'Detalle'}
function ModalContent({modal,selected,data,role,onClose,onToast,onUpdate,onApprove,onSubmitOrder,onAddEmployee,onAddProduct,onRegisterGuide,onConfirmReceive,onIncidentChange,onOpen,onLog}:{modal:string;selected:string;data:AppData;role:Role;onClose:()=>void;onToast:(s:string)=>void;onUpdate:(fn:(d:AppData)=>AppData)=>void;onApprove:(o:Order)=>void;onSubmitOrder:(f:HTMLFormElement)=>void;onAddEmployee:(f:HTMLFormElement)=>void;onAddProduct:(f:HTMLFormElement)=>void;onRegisterGuide:(f:HTMLFormElement)=>void;onConfirmReceive:(id:string,diff?:string)=>void;onIncidentChange:(id:string,status:string,resolution?:string)=>void;onOpen:(m:string,s?:string)=>void;onLog:(a:string,d:string)=>void}){
 const order=data.orders.find(o=>o.id===selected);const employee=data.employees.find(e=>e.id===selected);const product=data.products.find(p=>p.id===selected);const inv=data.inventory.find(i=>i.id===selected);const pkg=data.packages.find(p=>p.id===selected);const incident=data.incidents.find(i=>i.id===selected);
 const [pickedEmployee,setPickedEmployee]=useState(data.employees[0]?.id||'');const [pickedProduct,setPickedProduct]=useState(data.products[0]?.id||'');const [pickedSize,setPickedSize]=useState('M');const [pickedOrder,setPickedOrder]=useState(data.orders.find(o=>o.status==='En preparación'||o.status==='Aprobado')?.id||data.orders[0]?.id||'');const [diff,setDiff]=useState('');const [resolution,setResolution]=useState('');const [rating,setRating]=useState('5');const [note,setNote]=useState('');const [checked,setChecked]=useState(false);const canvasRef=useRef<HTMLCanvasElement|null>(null);const drawing=useRef(false);const hasInk=useRef(false);
 useEffect(()=>{if(modal==='deliver'&&canvasRef.current){const c=canvasRef.current;const ctx=c.getContext('2d');if(ctx){ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#142b4a'}}},[modal]);
 const drawStart=(e:React.MouseEvent<HTMLCanvasElement>|React.TouchEvent<HTMLCanvasElement>)=>{drawing.current=true;const c=canvasRef.current;if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;const r=c.getBoundingClientRect();const point='touches'in e?e.touches[0]:e;ctx.beginPath();ctx.moveTo(point.clientX-r.left,point.clientY-r.top);hasInk.current=true};
 const drawMove=(e:React.MouseEvent<HTMLCanvasElement>|React.TouchEvent<HTMLCanvasElement>)=>{if(!drawing.current)return;if('touches'in e)e.preventDefault();const c=canvasRef.current;if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;const r=c.getBoundingClientRect();const point='touches'in e?e.touches[0]:e;ctx.lineTo(point.clientX-r.left,point.clientY-r.top);ctx.stroke()};
 const drawEnd=()=>{drawing.current=false};
 const clearSignature=()=>{const c=canvasRef.current;if(c)c.getContext('2d')?.clearRect(0,0,c.width,c.height);hasInk.current=false};
 if(modal==='new-order')return <form className="form-stack" onSubmit={e=>{e.preventDefault();onSubmitOrder(e.currentTarget)}}><div className="form-note"><ClipboardList size={18}/><span>El pedido se guardará como <b>En revisión</b>. Los productos se validan según el puesto del empleado.</span></div><div className="form-grid"><label>Sucursal<select name="branch" defaultValue={role==='Representante de sucursal'?'Toluca':'Toluca'}>{['Toluca','Querétaro','Puebla'].map(b=><option key={b}>{b}</option>)}</select></label><label>Empleado destinatario<select name="employee" value={pickedEmployee} onChange={e=>setPickedEmployee(e.target.value)}>{data.employees.filter(e=>e.active).map(e=><option key={e.id} value={e.id}>{e.name} · {e.job}</option>)}</select></label><label>Producto<select name="product" value={pickedProduct} onChange={e=>{setPickedProduct(e.target.value);const p=data.products.find(x=>x.id===e.target.value);setPickedSize(p?.sizes[0]||'M')}}>{data.products.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name} ({p.sku})</option>)}</select></label><label>Talla / variante<select name="size" value={pickedSize} onChange={e=>setPickedSize(e.target.value)}>{(data.products.find(p=>p.id===pickedProduct)?.sizes||['M']).map(s=><option key={s}>{s}</option>)}</select></label><label>Cantidad<input name="qty" type="number" min="1" defaultValue="1" required/></label><label>Justificación de excepción <span className="optional">(si aplica)</span><input name="exception" placeholder="Obligatoria si el producto no está autorizado"/></label></div>{(()=>{const e=data.employees.find(x=>x.id===pickedEmployee);const p=data.products.find(x=>x.id===pickedProduct);const allowed=!!e&&!!p&&p.jobs.includes(e.job);return <div className={`eligibility ${allowed?'allowed':'not-allowed'}`}>{allowed?<CheckCircle2 size={17}/>:<AlertTriangle size={17}/>}<span>{allowed?`Producto autorizado para ${e?.job}.`:`Este producto no está autorizado para ${e?.job||'el puesto seleccionado'}. Debes justificar una excepción y quedará pendiente de autorización.`}</span></div>})()}<label>Observaciones<textarea name="note" rows={2} placeholder="Comentarios para la revisión…"/></label><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary" type="submit"><Check size={16}/> Enviar a revisión</button></div></form>;
 if(modal==='new-employee')return <form className="form-stack" onSubmit={e=>{e.preventDefault();onAddEmployee(e.currentTarget)}}><div className="form-grid"><label>Número de empleado<input name="number" placeholder="Ej. 1013" required/></label><label>Nombre completo<input name="name" placeholder="Nombre y apellidos" required/></label><label>Sucursal<select name="branch">{['Toluca','Querétaro','Puebla'].map(b=><option key={b}>{b}</option>)}</select></label><label>Puesto<select name="job">{['Administración','Enfermería','Mantenimiento','Seguridad','Intendencia','Almacén'].map(j=><option key={j}>{j}</option>)}</select></label></div><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Plus size={16}/> Crear empleado</button></div></form>;
 if(modal==='new-product')return <form className="form-stack" onSubmit={e=>{e.preventDefault();onAddProduct(e.currentTarget)}}><div className="form-grid"><label>SKU<input name="sku" placeholder="UNI-010" required/></label><label>Nombre<input name="name" placeholder="Nombre del producto" required/></label><label>Categoría<select name="category">{['Batas','Prendas','Protección','Calzado','Accesorios'].map(c=><option key={c}>{c}</option>)}</select></label><label>Precio de referencia (MXN)<input name="price" type="number" min="0" defaultValue="0"/></label><label>Tallas / variantes <span className="optional">(separadas por coma)</span><input name="sizes" defaultValue="S,M,L,XL"/></label><label>Puestos autorizados <span className="optional">(separados por coma)</span><input name="jobs" defaultValue="Administración"/></label></div><div className="form-note"><AlertTriangle size={17}/><span>Las reglas y precios son de demostración. Verifica las políticas de la empresa antes de producción.</span></div><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Plus size={16}/> Agregar producto</button></div></form>;
 if(modal==='order-detail'&&order)return <div className="detail-stack"><div className="detail-summary"><div><span className="detail-label">FOLIO DEL PEDIDO</span><h3>{order.id}</h3><p>Creado el {order.created} · Sucursal {order.branch}</p></div><Status value={order.status}/></div><div className="detail-kpis"><div><span>Empleados</span><b>{new Set(order.items.map(i=>i.employeeId)).size}</b></div><div><span>Artículos</span><b>{order.items.reduce((n,i)=>n+i.qty,0)}</b></div><div><span>Importe de referencia</span><b>{money(order.items.reduce((n,i)=>n+(data.products.find(p=>p.id===i.productId)?.price||0)*i.qty,0))}</b></div></div><h3 className="section-title">Empleados y artículos</h3><table><thead><tr><th>EMPLEADO</th><th>PRODUCTO</th><th>TALLA</th><th>CANT.</th><th>VALIDACIÓN</th></tr></thead><tbody>{order.items.map((it,i)=>{const emp=data.employees.find(e=>e.id===it.employeeId);const p=data.products.find(x=>x.id===it.productId);return <tr key={i}><td>{emp?.name||it.employeeId}<small className="cell-sub">{emp?.job}</small></td><td>{p?.name||it.productId}</td><td>{it.size}</td><td>{it.qty}</td><td>{it.exception?<Status value="Excepción pendiente"/>:<Status value="Validado"/>}</td></tr>})}</tbody></table>{order.note&&<div className="note-box"><b>Observaciones</b><p>{order.note}</p></div>}{order.inventoryId&&<div className="success-note"><CheckCircle2 size={17}/> Orden de inventario generada: <b>{order.inventoryId}</b></div>}{order.status==='En revisión'&&canApprove(role)&&<div className="modal-actions"><button className="btn danger" onClick={()=>onOpen('reject-order',order.id)}>Devolver / rechazar</button><button className="btn primary" onClick={()=>onApprove(order)}><Check size={16}/> Aprobar y generar orden</button></div>}{order.status==='Aprobado'&&<div className="modal-actions"><button className="btn primary" onClick={()=>{onClose();onOpen('new-package',order.id)}}><Package size={16}/> Preparar paquete</button></div>}</div>;
 if(modal==='reject-order'&&order)return <form className="form-stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const reason=String(f.get('reason')||'');if(!reason.trim()){onToast('Indica el motivo.');return}onUpdate(d=>{const o=d.orders.find(x=>x.id===order.id)!;o.status=String(f.get('decision')||'Devuelto para corrección');o.note+=`\n${o.status}: ${reason}`;d.audit.unshift({id:id('AUD'),date:now(),user:role,action:o.status,detail:`${o.id} · ${reason}`});d.notifications.unshift({id:id('NOT'),text:`El pedido ${o.id} fue ${o.status.toLowerCase()}.`,read:false,date:today()});return d});onClose();onToast('Decisión registrada con motivo.')}}><div className="form-note"><AlertTriangle size={17}/><span>La decisión quedará registrada en el historial del pedido.</span></div><label>Decisión<select name="decision"><option>Devuelto para corrección</option><option>Rechazado</option></select></label><label>Motivo obligatorio<textarea name="reason" rows={3} required placeholder="Describe qué debe corregirse o por qué se rechaza…"/></label><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn danger">Registrar decisión</button></div></form>;
 if(modal==='employee-detail'&&employee)return <div className="detail-stack"><div className="person-hero"><div className="avatar large">{employee.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><h3>{employee.name}</h3><p>{employee.job} · {employee.branch}</p><Status value={employee.active?'Activo':'Inactivo'}/></div></div><div className="detail-kpis"><div><span>Número</span><b>{employee.number}</b></div><div><span>Fecha de alta</span><b>{employee.joined}</b></div><div><span>Pedidos relacionados</span><b>{data.orders.filter(o=>o.items.some(i=>i.employeeId===employee.id)).length}</b></div></div><h3 className="section-title">Historial de pedidos</h3>{data.orders.filter(o=>o.items.some(i=>i.employeeId===employee.id)).map(o=><div className="history-card" key={o.id}><div><b>{o.id}</b><small>{o.created}</small></div><Status value={o.status}/><button className="row-action" onClick={()=>onOpen('order-detail',o.id)}><ArrowRight size={16}/></button></div>)}</div>;
 if(modal==='product-detail'&&product)return <div className="detail-stack"><div className="product-hero"><div className="product-hero-icon"><Shirt size={36}/></div><div><span className="product-sku">{product.sku}</span><h3>{product.name}</h3><p>{product.category}</p><h2>{money(product.price)} <small>MXN de referencia</small></h2></div></div><div className="detail-block"><b>Tallas y variantes</b><div className="size-row">{product.sizes.map(s=><span key={s}>{s}</span>)}</div></div><div className="detail-block"><b>Puestos autorizados</b><div className="job-tags">{product.jobs.map(j=><span key={j}>{j}</span>)}</div></div><div className="detail-block"><b>Estado</b><Status value={product.active?'Activo':'Inactivo'}/></div><div className="disclaimer">Información ficticia para demostración.</div></div>;
 if(modal==='inventory-detail'&&inv){const o=data.orders.find(x=>x.id===inv.orderId);return <div className="detail-stack"><div className="detail-summary"><div><span className="detail-label">ORDEN DE INVENTARIO</span><h3>{inv.id}</h3><p>Pedido de origen {inv.orderId} · {inv.branch}</p></div><Status value={inv.status}/></div><h3 className="section-title">Detalle de artículos</h3>{o?.items.map((it,i)=><div className="history-card" key={i}><div><b>{data.products.find(p=>p.id===it.productId)?.name}</b><small>{data.employees.find(e=>e.id===it.employeeId)?.name} · Talla {it.size}</small></div><span className="quantity">× {it.qty}</span></div>)}<div className="modal-actions"><button className="btn secondary" onClick={()=>{const rows=(o?.items||[]).map(it=>({orden:inv.id,pedido:inv.orderId,sucursal:inv.branch,empleado:data.employees.find(e=>e.id===it.employeeId)?.name,producto:data.products.find(p=>p.id===it.productId)?.name,talla:it.size,cantidad:it.qty}));const csv=['orden,pedido,sucursal,empleado,producto,talla,cantidad',...rows.map(r=>Object.values(r).map(v=>`"${String(v??'')}"`).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download=`${inv.id}.csv`;a.click();URL.revokeObjectURL(a.href);onToast('Detalle de orden exportado.')}}><Download size={15}/> Exportar detalle CSV</button>{inv.status!=='Liberada para preparación'&&<button className="btn primary" onClick={()=>{onUpdate(d=>{const x=d.inventory.find(z=>z.id===inv.id)!;x.status='Liberada para preparación';return d});onClose();onToast('Orden liberada para preparación.')}}><Check size={15}/> Liberar para preparación</button>}</div></div>}
 if(modal==='new-package')return <form className="form-stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const oid=String(f.get('order')||'');const o=data.orders.find(x=>x.id===oid);if(!o){onToast('Selecciona un pedido.');return}if(!data.inventory.some(i=>i.orderId===oid)){onToast('Primero debe aprobarse el pedido y generarse su orden de inventario.');return}if(data.packages.some(p=>p.orderId===oid&&!p.received)){onToast('Este pedido ya tiene un paquete activo. Confirma su recepción antes de crear otro.');return}const people:string[]=[...new Set<string>(o.items.map(i=>i.employeeId))];onUpdate(d=>{const pid=id('PAQ-2026');d.packages.unshift({id:pid,orderId:oid,employeeIds:people,status:'Preparado',tracking:['Paquete preparado · '+today()],received:false});const inv=d.inventory.find(i=>i.orderId===oid);if(inv)inv.status='En preparación';const sourceOrder=d.orders.find(x=>x.id===oid);if(sourceOrder)sourceOrder.status='En preparación';d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Paquete creado',detail:`${pid} · ${oid}`});return d});onClose();onToast('Paquete creado. Los kits quedaron asignados a este paquete.')}}><div className="form-note"><Package size={18}/><span>La demostración asigna al paquete los empleados y kits del pedido seleccionado, evitando duplicar asignaciones.</span></div><label>Pedido aprobado<select name="order" defaultValue={selected||pickedOrder}>{data.orders.filter(o=>data.inventory.some(i=>i.orderId===o.id)&&!['Completado','Rechazado'].includes(o.status)).map(o=><option key={o.id} value={o.id}>{o.id} · {o.branch} · {o.status}</option>)}</select></label><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Package size={16}/> Crear paquete</button></div></form>;
 if((modal==='new-guide'||modal==='new-guide') )return <form className="form-stack" onSubmit={e=>{e.preventDefault();onRegisterGuide(e.currentTarget)}}><label>Paquete preparado<select name="package" defaultValue={selected||''} required>{data.packages.filter(p=>!p.guide&&p.status==='Preparado').map(p=><option key={p.id} value={p.id}>{p.id} · {p.orderId}</option>)}</select></label><div className="form-grid"><label>Transportista<select name="carrier"><option>Transportes Castores</option><option>Estafeta (simulado)</option><option>FedEx (simulado)</option><option>Otro</option></select></label><label>Número de guía<input name="guide" required placeholder="CAST-000000"/></label></div><label>Observaciones<textarea name="note" rows={2} placeholder="Información adicional…"/></label><div className="form-note"><Truck size={17}/><span>El seguimiento es ficticio. No existe conexión con Transportes Castores ni con otra paquetería.</span></div><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Check size={15}/> Guardar guía</button></div></form>;
 if(modal==='package-detail'&&pkg)return <div className="detail-stack"><div className="detail-summary"><div><span className="detail-label">PAQUETE</span><h3>{pkg.id}</h3><p>Pedido {pkg.orderId}</p></div><Status value={pkg.status}/></div><div className="detail-kpis"><div><span>Empleados / kits</span><b>{pkg.employeeIds.length}</b></div><div><span>Guía</span><b>{pkg.guide||'Sin registrar'}</b></div><div><span>Recepción</span><b>{pkg.received?'Confirmada':'Pendiente'}</b></div></div><h3 className="section-title">Contenido asignado</h3>{pkg.employeeIds.map(eid=><div className="history-card" key={eid}><div><b>{data.employees.find(e=>e.id===eid)?.name||eid}</b><small>{data.orders.find(o=>o.id===pkg.orderId)?.items.filter(i=>i.employeeId===eid).map(i=>`${data.products.find(p=>p.id===i.productId)?.name} · Talla ${i.size} · ×${i.qty}`).join(' / ')}</small></div><Status value={data.deliveries.find(d=>d.packageId===pkg.id&&d.employeeId===eid)?.status||'Pendiente'}/></div>)}<h3 className="section-title">Historial logístico</h3>{pkg.tracking.map((t,i)=><div className="tracking-event" key={i}><div className="tracking-dot"/><span>{t}</span></div>)}{pkg.difference&&<div className="warning-note"><AlertTriangle size={17}/><p>Diferencias registradas: {pkg.difference}</p></div>}</div>;
 if(modal==='tracking-detail'&&pkg)return <div className="detail-stack"><div className="detail-summary"><div><span className="detail-label">GUÍA DE TRANSPORTE</span><h3>{pkg.guide}</h3><p>{pkg.carrier} · {pkg.id}</p></div><Status value={pkg.status}/></div><div className="tracking-list">{pkg.tracking.map((t,i)=><div className="tracking-event" key={i}><div className="tracking-dot"/><div><b>{t.split(' · ')[0]}</b><small>{t.split(' · ').slice(1).join(' · ')}</small></div></div>)}</div><div className="form-note"><AlertTriangle size={17}/><span>El evento “Entregado por transportista” no confirma la recepción en sucursal. Esa operación requiere verificación por separado.</span></div><div className="modal-actions"><button className="btn secondary" onClick={onClose}>Cerrar</button>{pkg.status!=='Entregado por transportista'&&<button className="btn primary" onClick={()=>{const stages=['En tránsito','Llegada a centro de distribución','En reparto','Entregado por transportista'];onUpdate(d=>{const p=d.packages.find(x=>x.id===pkg.id)!;const next=stages.find(s=>!p.tracking.some(t=>t.startsWith(s)));if(next){p.tracking.push(`${next} · ${today()} (simulado)`);p.status=next}return d});onClose();onToast('Siguiente evento simulado registrado.')}}>Simular siguiente evento <ArrowRight size={15}/></button>}</div></div>;
 if(modal==='receive-package'&&pkg)return <form className="form-stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const difference=String(f.get('difference')||'');onConfirmReceive(pkg.id,difference);onClose()}}><div className="form-note"><PackageCheck size={18}/><span>Confirma únicamente lo que recibiste físicamente. Los kits seguirán pendientes de entrega individual.</span></div><div className="detail-kpis"><div><span>Paquete</span><b>{pkg.id}</b></div><div><span>Kits esperados</span><b>{pkg.employeeIds.length}</b></div><div><span>Guía</span><b>{pkg.guide||'—'}</b></div></div><label>Resultado de verificación<select name="difference" value={diff} onChange={e=>setDiff(e.target.value)}><option value="">Recepción completa, sin diferencias</option><option>Paquete dañado</option><option>Faltan artículos</option><option>Sobrantes</option><option>Paquete incorrecto</option><option>Paquete no recibido</option><option>Otro</option></select></label>{diff&&<div className="warning-note"><AlertTriangle size={17}/><p>Se generará una incidencia y la recepción quedará marcada con diferencias.</p></div>}<div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Check size={16}/> Confirmar recepción</button></div></form>;
 if(modal==='deliver'){const delivery=data.deliveries.find(d=>d.id===selected);const emp=data.employees.find(e=>e.id===delivery?.employeeId);const o=data.orders.find(x=>x.id===delivery?.orderId);const its=o?.items.filter(i=>i.employeeId===delivery?.employeeId)||[];return <form className="form-stack" onSubmit={e=>{e.preventDefault();if(!hasInk.current){onToast('Captura la firma del empleado antes de confirmar.');return}if(!checked){onToast('Confirma que revisaste los artículos entregados.');return}const c=canvasRef.current;const signature=c?.toDataURL('image/png')||'';onUpdate(d=>{const del=d.deliveries.find(x=>x.id===selected)!;del.status='Entregado';del.signedAt=now();del.signature=signature;del.rating=Number(rating);del.note=note;d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Entrega individual confirmada',detail:`${emp?.name} · ${delivery?.orderId}`});const ord=d.orders.find(x=>x.id===delivery?.orderId);if(ord){const relevant=d.deliveries.filter(x=>x.orderId===ord.id);if(relevant.length>0&&relevant.every(x=>x.status==='Entregado'))ord.status='Completado'}d.notifications.unshift({id:id('NOT'),text:`Entrega individual confirmada para ${emp?.name}.`,read:false,date:today()});return d});onClose();onToast('Entrega registrada con firma y conformidad.')}}><div className="person-hero"><div className="avatar large">{emp?.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><h3>{emp?.name}</h3><p>{emp?.job} · {emp?.branch}</p><span className="muted small-text">Pedido {delivery?.orderId} · Paquete {delivery?.packageId}</span></div></div><h3 className="section-title">Artículos esperados</h3><div className="delivery-items">{its.map((it,i)=><div key={i}><div><b>{data.products.find(p=>p.id===it.productId)?.name}</b><small>Talla {it.size} · Cantidad {it.qty}</small></div><Status value={it.exception?'Excepción pendiente':'Esperado'}/></div>)}</div><label className="checkbox-line"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/> Confirmo que revisé los artículos, tallas y cantidades entregadas.</label><label>Valoración de conformidad<select value={rating} onChange={e=>setRating(e.target.value)}>{[5,4,3,2,1].map(n=><option key={n} value={n}>{n} de 5 {n===5?'· Excelente':n===4?'· Bueno':n===3?'· Regular':n===2?'· Malo':'· Muy malo'}</option>)}</select></label><label>Observaciones<textarea value={note} onChange={e=>setNote(e.target.value)} rows={2} placeholder="Comentarios del empleado…"/></label><div className="signature-label"><div><b>Firma de conformidad</b><small>Firma dibujada con mouse o dedo.</small></div><button type="button" className="text-button" onClick={clearSignature}>Borrar firma</button></div><canvas ref={canvasRef} width={520} height={150} className="signature-canvas" onMouseDown={drawStart} onMouseMove={drawMove} onMouseUp={drawEnd} onMouseLeave={drawEnd} onTouchStart={drawStart} onTouchMove={drawMove} onTouchEnd={drawEnd}/><div className="signature-foot"><span><Fingerprint size={14}/> La firma se guarda solo en este navegador.</span><span>Firma simple de demostración; no es firma electrónica avanzada.</span></div><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Check size={16}/> Confirmar entrega</button></div></form>}
 if(modal==='new-incident')return <form className="form-stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const iid=id('INC-2026');const oid=String(f.get('order')||data.orders[0]?.id);const eid=String(f.get('employee')||'');const incident={id:iid,orderId:oid,employeeId:eid||undefined,type:String(f.get('type')||'Otro'),priority:String(f.get('priority')||'Media'),status:'Abierta',description:String(f.get('description')||''),created:today()};onUpdate(d=>{d.incidents.unshift(incident);d.audit.unshift({id:id('AUD'),date:now(),user:role,action:'Incidencia registrada',detail:`${iid} · ${incident.type}`});d.notifications.unshift({id:id('NOT'),text:`Nueva incidencia ${iid}: ${incident.type}.`,read:false,date:today()});return d});onClose();onToast('Incidencia registrada.')}}><div className="form-grid"><label>Pedido relacionado<select name="order">{data.orders.map(o=><option key={o.id}>{o.id}</option>)}</select></label><label>Empleado afectado<select name="employee"><option value="">No aplica / paquete</option>{data.employees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label><label>Tipo<select name="type">{['Talla incorrecta','Artículo faltante','Artículo incorrecto','Artículo dañado','Kit incompleto','Paquete no recibido','Producto no autorizado','Otro'].map(t=><option key={t}>{t}</option>)}</select></label><label>Prioridad<select name="priority"><option>Baja</option><option selected>Media</option><option>Alta</option><option>Crítica</option></select></label></div><label>Descripción<textarea name="description" rows={3} required placeholder="Describe la incidencia y la evidencia disponible…"/></label><div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary"><Plus size={15}/> Registrar incidencia</button></div></form>;
 if(modal==='incident-detail'&&incident)return <div className="detail-stack"><div className="detail-summary"><div><span className="detail-label">INCIDENCIA</span><h3>{incident.id}</h3><p>{incident.type} · Creada {incident.created}</p></div><Status value={incident.status}/></div><div className="note-box"><b>Descripción original</b><p>{incident.description}</p><small>Pedido {incident.orderId} · Empleado {data.employees.find(e=>e.id===incident.employeeId)?.name||'No especificado'}</small></div><label>Estado<select value={incident.status} onChange={e=>onIncidentChange(incident.id,e.target.value)}>{['Abierta','En revisión','En resolución','Resuelta','Cerrada'].map(s=><option key={s}>{s}</option>)}</select></label><label>Resolución / comentario<textarea value={resolution||incident.resolution||''} onChange={e=>setResolution(e.target.value)} rows={3} placeholder="Describe la solución sin borrar la evidencia original…"/></label><div className="modal-actions"><button className="btn secondary" onClick={onClose}>Cerrar</button><button className="btn primary" onClick={()=>{onIncidentChange(incident.id,incident.status,resolution);onClose()}}><Check size={15}/> Guardar resolución</button></div></div>;
 return <div className="empty-state"><div><FileText size={24}/></div><b>Información no disponible</b><p>El registro puede haber cambiado o ya no existe.</p><button className="btn secondary" onClick={onClose}>Cerrar</button></div>;
}
function canApprove(role:Role){return role==='Administrador'||role==='Gerente de ventas'}
function Reports({data,exportCsv}:{data:AppData;exportCsv:(rows:Record<string,unknown>[],name:string)=>void}){const [report,setReport]=useState('Pedidos');const [branch,setBranch]=useState('Todas');const orders=data.orders.filter(o=>branch==='Todas'||o.branch===branch);const deliveries=data.deliveries.filter(d=>{const o=data.orders.find(x=>x.id===d.orderId);return branch==='Todas'||o?.branch===branch});return <><div className="report-kpis"><div className="panel"><span>Pedidos registrados</span><b>{orders.length}</b><small>En sucursales filtradas</small></div><div className="panel"><span>Kits / artículos</span><b>{orders.reduce((n,o)=>n+o.items.reduce((s,i)=>s+i.qty,0),0)}</b><small>Solicitados en pedidos</small></div><div className="panel"><span>Entregas completadas</span><b>{deliveries.filter(d=>d.status==='Entregado').length}</b><small>Conformidad individual</small></div><div className="panel"><span>Incidencias abiertas</span><b>{data.incidents.filter(i=>!['Resuelta','Cerrada'].includes(i.status)).length}</b><small>Requieren seguimiento</small></div></div><div className="panel"><div className="toolbar"><div className="filter-pills">{['Pedidos','Entregas','Incidencias','Paquetes'].map(s=><button className={report===s?'selected':''} key={s} onClick={()=>setReport(s)}>{s}</button>)}</div><div className="toolbar-right"><select value={branch} onChange={e=>setBranch(e.target.value)}><option>Todas</option><option>Toluca</option><option>Querétaro</option><option>Puebla</option></select><button className="btn primary" onClick={()=>{if(report==='Pedidos')exportCsv(orders.map(o=>({folio:o.id,fecha:o.created,sucursal:o.branch,empleados:new Set(o.items.map(i=>i.employeeId)).size,articulos:o.items.reduce((n,i)=>n+i.qty,0),estado:o.status})),'reporte-pedidos.csv');else if(report==='Entregas')exportCsv(deliveries.map(d=>({empleado:data.employees.find(e=>e.id===d.employeeId)?.name,pedido:d.orderId,paquete:d.packageId,estado:d.status,fecha:d.signedAt||'',valoracion:d.rating||''})),'reporte-entregas.csv');else if(report==='Incidencias')exportCsv(data.incidents.map(i=>({folio:i.id,tipo:i.type,pedido:i.orderId,prioridad:i.priority,estado:i.status,fecha:i.created,resolucion:i.resolution||''})),'reporte-incidencias.csv');else exportCsv(data.packages.map(p=>({paquete:p.id,pedido:p.orderId,guia:p.guide||'',kits:p.employeeIds.length,estado:p.status,recepcion:p.received?'Confirmada':'Pendiente'})),'reporte-paquetes.csv')}}><Download size={15}/> Exportar CSV</button></div></div>{report==='Pedidos'&&<table><thead><tr><th>FOLIO</th><th>FECHA</th><th>SUCURSAL</th><th>EMPLEADOS</th><th>ARTÍCULOS</th><th>ESTADO</th></tr></thead><tbody>{orders.map(o=><tr key={o.id}><td>{o.id}</td><td>{o.created}</td><td>{o.branch}</td><td>{new Set(o.items.map(i=>i.employeeId)).size}</td><td>{o.items.reduce((n,i)=>n+i.qty,0)}</td><td><Status value={o.status}/></td></tr>)}</tbody></table>}{report==='Entregas'&&<table><thead><tr><th>EMPLEADO</th><th>PEDIDO</th><th>PAQUETE</th><th>ESTADO</th><th>FECHA</th></tr></thead><tbody>{deliveries.map(d=><tr key={d.id}><td>{data.employees.find(e=>e.id===d.employeeId)?.name}</td><td>{d.orderId}</td><td>{d.packageId}</td><td><Status value={d.status}/></td><td>{d.signedAt||'—'}</td></tr>)}</tbody></table>}{report==='Incidencias'&&<table><thead><tr><th>FOLIO</th><th>TIPO</th><th>PEDIDO</th><th>PRIORIDAD</th><th>ESTADO</th></tr></thead><tbody>{data.incidents.map(i=><tr key={i.id}><td>{i.id}</td><td>{i.type}</td><td>{i.orderId}</td><td><Status value={i.priority}/></td><td><Status value={i.status}/></td></tr>)}</tbody></table>}{report==='Paquetes'&&<table><thead><tr><th>PAQUETE</th><th>PEDIDO</th><th>GUÍA</th><th>KITS</th><th>ESTADO</th><th>RECEPCIÓN</th></tr></thead><tbody>{data.packages.map(p=><tr key={p.id}><td>{p.id}</td><td>{p.orderId}</td><td>{p.guide||'—'}</td><td>{p.employeeIds.length}</td><td><Status value={p.status}/></td><td>{p.received?'Confirmada':'Pendiente'}</td></tr>)}</tbody></table>}</div><div className="panel report-chart"><div className="panel-header"><div><h2>Resumen de pedidos por estado</h2><p>Conteo calculado desde los registros actuales</p></div><FileBarChart size={19} className="muted"/></div><div className="status-chart">{['En revisión','Aprobado','En preparación','En tránsito','Completado','Rechazado'].map((s,i)=>{const n=orders.filter(o=>o.status===s).length;const max=Math.max(1,...orders.map(o=>orders.filter(x=>x.status===x.status).length));return <div className="bar-row" key={s}><div><span>{s}</span><b>{n}</b></div><div className="bar-track"><div className={`bar-fill b${i%5}`} style={{width:`${n/Math.max(1,orders.length)*100}%`}}/></div></div>})}</div></div></>}
function DemoPage({data,go,onReset}:{data:AppData;go:(p:string)=>void;onReset:()=>void}){const steps=[{title:'Crear pedido',desc:'El representante selecciona empleados, productos y tallas.',role:'Representante de sucursal',page:'orders',done:data.orders.some(o=>o.id==='PED-2026-001'||o.status!=='Borrador')},{title:'Enviar a revisión',desc:'El pedido queda en la bandeja del gerente.',role:'Representante de sucursal',page:'orders',done:data.orders.some(o=>o.status==='En revisión')},{title:'Aprobar pedido',desc:'El gerente valida la solicitud y genera una orden de inventario.',role:'Gerente de ventas',page:'approvals',done:data.orders.some(o=>o.inventoryId)},{title:'Liberar inventario',desc:'El responsable libera la orden autorizada.',role:'Responsable de inventario',page:'inventory',done:data.inventory.some(i=>i.status==='Liberada para preparación'||i.status==='En preparación')},{title:'Preparar paquetes',desc:'Se agrupan kits por empleado y se crea el paquete.',role:'Responsable de inventario',page:'packages',done:data.packages.length>0},{title:'Registrar guías',desc:'Se captura el transportista y la guía ficticia.',role:'Responsable de inventario',page:'shipments',done:data.packages.some(p=>!!p.guide)},{title:'Simular envío',desc:'Avanza los eventos de transporte sin confirmar la recepción.',role:'Responsable de inventario',page:'shipments',done:data.packages.some(p=>p.status==='Entregado por transportista'||p.received)},{title:'Confirmar recepción',desc:'El representante verifica físicamente el contenido del paquete.',role:'Representante de sucursal',page:'receiving',done:data.packages.some(p=>p.received)},{title:'Entregar y cerrar',desc:'Cada empleado firma su propia conformidad o registra una incidencia.',role:'Representante de sucursal',page:'deliveries',done:data.deliveries.length>0&&data.deliveries.every(d=>d.status==='Entregado')}];const next=steps.find(s=>!s.done);return <><div className="demo-hero"><div className="demo-hero-icon"><ListChecks size={26}/></div><div><span className="eyebrow">RECORRIDO GUIADO</span><h2>De la solicitud a la conformidad</h2><p>Completa las etapas en orden. El simulador no omite aprobaciones, recepciones físicas ni firmas.</p></div><button className="btn secondary" onClick={onReset}><RotateCcw size={15}/> Reiniciar demo</button></div><div className="demo-progress"><div><span>Progreso del recorrido</span><b>{steps.filter(s=>s.done).length} de {steps.length} etapas</b></div><div className="progress-track"><div style={{width:`${steps.filter(s=>s.done).length/steps.length*100}%`}}/></div></div><div className="demo-steps">{steps.map((s,i)=><div className={`demo-step ${s.done?'done':''} ${next?.title===s.title?'current':''}`} key={s.title}><div className="step-rail"><div className="step-circle">{s.done?<Check size={17}/>:i+1}</div>{i<steps.length-1&&<div className="step-line"/>}</div><div className="step-main"><div className="step-top"><h3>{s.title}</h3><Status value={s.done?'Completado':next?.title===s.title?'Siguiente paso':'Pendiente'}/></div><p>{s.desc}</p><div className="step-meta"><span><Users size={14}/>{s.role}</span></div></div><button className={`btn ${next?.title===s.title?'primary':'secondary'}`} onClick={()=>go(s.page)}>{next?.title===s.title?'Continuar':'Abrir módulo'} <ArrowRight size={15}/></button></div>)}</div><div className="info-banner"><div className="info-icon"><ShieldCheck size={20}/></div><div><b>Separación de responsabilidades</b><p>El transportista puede marcar un envío como entregado, pero solo el representante confirma la recepción y cada empleado confirma su kit individual.</p></div></div></>}
